    [3, 3, 3, 3, 4, 4]
    """
    if not numbers or window_size == 0:
        return []
    max_index = 0
    result = []
    for i in range(window_size - 1, len(numbers)):
        if numbers[i] >= numbers[max_index]:
            max_index = i
        result.append(numbers[max_index])
