    """ From a given list of integers, return a longest decreasing subsequence of integers found in given
    sequence.
    >>> longest_decreasing_subsequence([10, 9, 2, 5, 3, 7, 101, 18])
    [101, 18, 10, 7, 3]
    """
    result = [numbers[0]]
    for n in numbers[1:]:
        if n < result[-1]:
