            result[i] = n
    return result[::-1]


def longest_decreasing_subsequence_of_size_k(numbers: List[int], k: int) -> List[int]:
    """ From a given list of integers, return a longest decreasing subsequence of integers found in given
    sequence of given length.
    >>> longest_decreasing_subsequence_of_size_k([10, 9, 2, 5, 3, 7, 101, 18], 4)
    [101, 18, 10, 7]
    """
    if k == 0:
        return []
    if k == 1:
        return [min(numbers)]
    dp = [[float('-inf')] * (k + 1) for _ in range(len(numbers))]
    for i in range(len(numbers)):
