    for i in range(len(numbers)):
        for j in range(2, k + 1):
            dp[i][j] = max(dp[i][j], max([dp[j-1][1]] + [dp[j-1][x] + numbers[i] for x in range(j)]))
    result = [float('-inf')] * (k + 1)
    for j in range(1, k + 1):
        result[j] = max(result[j], dp[len(numbers) - 1][j])
