    """ For a given list of integers, return all unique triplets in that list that sum up to zero.
    >>> three_number_sum([-1, 0, 1, 2, -1, -4])
    [(-1, -1, 2), (-1, 0, 1)]
    """
    result = []
    sequence.sort()
    for i in range(len(sequence) - 2):
        if i > 0 and sequence[i] == sequence[i - 1]:
            continue
        left, right = i + 1, len(sequence) - 1
        while left < right:
            total = sequence[i] + sequence[left] + sequence[right]
            if total == 0:
                result.append((sequence[i], sequence[left], sequence[right]))
                while left < right and sequence[left] == sequence[left + 1]:
                    left += 1
                while left < right and sequence[right] == sequence[right - 1]:
