    """ Return the longest palindrome from given sequence. If multiple palindromes have the same length,
    return the first one encountered.
    >>> longest_palindrome('babad')
    'bab'
    """
    def expand_around_center(left: int, right: int) -> str:
        while left >= 0 and right < len(sequence) and sequence[left] == sequence[right]:
            left -= 1
            right += 1
