    """ From a given list of integers, generate a tuple containing indices of start and end of the longest
    subarray with a given sum.
    >>> longest_subarray_with_sum(5, [1, 2, 3, 2, 3, 4, 2])
    (0, 2)
    """
    if not numbers:
        return (-1, -1)

    current_sum = 0
    start = 0
    max_length = 0
    max_start = -1

    for end in range(len(numbers)):
        current_sum += numbers[end]

        while current_sum > target and start <= end:
            current_sum -= numbers[start]
            start += 1

        if current_sum == target:
            if end - start + 1 > max_length:
                max_length = end - start + 1
                max_start = start

    if max_start == -1:
        return (-1, -1)
    else:
        return (max_start, max_start + max_length - 1)


