    """ From a given list of integers, generate a tuple containing indices of start and end of the longest
    subarray with a zero sum.
    >>> longest_subarray_with_zero_sum([1, 2, -3, 4, -1, 2])
    (2, 5)
    """
    if not numbers:
        return (-1, -1)

    current_sum = 0
    start = 0
    max_length = 0
    max_start = -1

    sum_index_dict = {0: -1}

    for end in range(len(numbers)):
        current_sum += numbers[end]

        if current_sum in sum_index_dict:
            if end - sum_index_dict[current_sum] > max_length:
                max_length = end - sum_index_dict[current_sum]
                max_start = sum_index_dict[current_sum] + 1
        else:
