    """ From a given list of integers, generate a tuple containing indices of start and end of the longest
    subarray with unique elements.
    >>> longest_subarray_with_unique_elements([1, 2, 3, 2, 1, 4])
    (0, 4)
    """
    if not numbers:
        return (-1, -1)

    current_start = 0
    max_length = 0
    max_start = -1

    seen_elements = set()

    for current_end in range(len(numbers)):
        while numbers[current_end] in seen_elements:
            seen_elements.remove(numbers[current_start])
            current_start += 1

        seen_elements.add(numbers[current_end])

        if current_end - current_start + 1 > max_length:
            max_length = current_end - current_start + 1
            max_start = current_start

    return (max_start, max_start + max_length - 1)


