package main

import (
	"fmt"
	"sort"
)

func sortEven(l []int) []int {
	evenIndices := make([]int, 0)
	for i, v := range l {
		if i%2 == 0 {
			evenIndices = append(evenIndices, v)
		}
	}

	sort.Ints(evenIndices)

	result := make([]int, len(l))
	evenIndex := 0
	for i, v := range l {
		if i%2 == 0 {
			result[i] = evenIndices[evenIndex]
			evenIndex++
		} else {
			result[i] = v
		}
	}

	return result
}

func checkFunction(f func([]int) []int) {
	fmt.Println(f([]int{1, 2, 3})) // [1, 2, 3]
	fmt.Println(f([]int{5, 6, 3, 4})) // [3, 6, 5, 4]
}

func main() {
	checkFunction(sortEven)
