fn sort_even(l: Vec<i32>) -> Vec<i32> {
    let mut even_indices: Vec<i32> = l.iter().enumerate().filter_map(|(i, &v)| if i % 2 == 0 { Some(v) } else { None }).collect();
    even_indices.sort_unstable();

    let mut result: Vec<i32> = vec![0; l.len()];
    let mut even_index = 0;

    for (i, v) in l.iter().enumerate() {
        if i % 2 == 0 {
            result[i] = even_indices[even_index];
            even_index += 1;
        } else {
            result[i] = *v;
        }
    }

    result
}

