def length_of_lis(nums):
    """Your task is to write a function that returns the length of the longest increasing subsequence in an array of integers.
    The function should have a time complexity of O(n log n).
    For example:
    length_of_lis([10, 9, 2, 5, 3, 7, 101, 18]) => 4
    length_of_lis([0, 1, 0, 3, 2, 3]) => 4
    length_of_lis([7, 7, 7, 7, 7, 7, 7]) => 1
    """
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)
